package com.bnfix.ubm.domains.partnership;
import com.bnfix.ubm.domains.partnership.dto.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import java.util.List;
@RestController@RequestMapping("/partnerships")public class PartnershipController{private final PartnershipService s;public PartnershipController(PartnershipService s){this.s=s;}private Long c(Jwt j){Object v=j.getClaims().get("companyId");return v instanceof Number n?n.longValue():Long.valueOf(v.toString());}@PostMapping@PreAuthorize("hasRole('MANAGER')")public PartnershipResponse request(@Valid@RequestBody CreatePartnershipRequest r,@AuthenticationPrincipal Jwt j){return s.request(j.getSubject(),c(j),r.benefitId());}@GetMapping("/provider/pending")@PreAuthorize("hasRole('MANAGER')")public List<PartnershipResponse> pending(@AuthenticationPrincipal Jwt j){return s.pending(j.getSubject(),c(j));}@PutMapping("/accept")@PreAuthorize("hasRole('MANAGER')")public PartnershipResponse accept(@RequestParam Long partnershipId,@AuthenticationPrincipal Jwt j){return s.transition(j.getSubject(),c(j),partnershipId,PartnershipStatus.ACTIVE);}@PutMapping("/reject")@PreAuthorize("hasRole('MANAGER')")public PartnershipResponse reject(@RequestParam Long partnershipId,@AuthenticationPrincipal Jwt j){return s.transition(j.getSubject(),c(j),partnershipId,PartnershipStatus.REJECTED);}@PutMapping("/disable")@PreAuthorize("hasRole('MANAGER')")public PartnershipResponse disable(@RequestParam Long partnershipId,@AuthenticationPrincipal Jwt j){return s.transition(j.getSubject(),c(j),partnershipId,PartnershipStatus.DISABLED);}}
